\begin{theorem}[Protected replacement on a three-torus]
\label{thm:prime-index-zero}
\uses{thm:prime-maximal-cut}
\lean{PoincareMT.M76.hasHamiltonProtectedIrreducibleReplacement_of_card_eq_zero}
For $i=0$, the protected marked ball admits an irreducible atlas on the
same lattice-handle ambient space. Both PL identity maps remain valid
on an open neighborhood of that entire ball.
\end{theorem}

